llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "2-Methoxyestradiol, a close estradiol analogue with a phenolic A-ring, had oral bioavailability of only 1–2% in patients, directly supporting low F for the query's estradiol-like scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Pentazocine, a phenolic fused-ring opioid, had mean oral bioavailability of 18% in healthy subjects, below the 20% threshold, supporting low F for a similarly lipophilic phenolic molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Progesterone, a steroid with comparable lipophilicity and ring system, has oral bioavailability less than 10% in humans due to poor solubility and gut/liver metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Butorphanol, a phenolic morphinan, has absolute oral bioavailability of 5–17%, well below 20%, consistent with extensive first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Loperamide, a lipophilic P-gp substrate, has absolute oral bioavailability of 0.3%, showing that high lipophilicity alone does not ensure F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Estramustine phosphate, an estradiol-based prodrug, showed mean oral bioavailability of 43.7% in patients, but this reflects a water-soluble phosphate prodrug rather than the highly lipophilic ester in the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C40"],
      "claim": "Danazol, a lipophilic steroid, reached 56% absolute oral bioavailability in the fed state as an emulsion, but fasted-state F was only 11–19%, so the high value depends on formulation and food.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a highly lipophilic estradiol 17-cyclopentylpropionate ester. Multiple high-transfer analogues with phenolic/steroid scaffolds (2-methoxyestradiol, progesterone, pentazocine, butorphanol, loperamide) show oral F below 20%, often <10%, due to poor solubility and first-pass metabolism. The few high-F values come from water-soluble phosphate prodrugs or fed-state lipid formulations and are less transferable. Therefore predict low oral bioavailability at the F≥20% threshold.",
  "evidence_gaps": [
    "No direct oral bioavailability data for estradiol cypionate itself.",
    "Food effects and lipid-based formulations could raise F above 20%, as seen with danazol.",
    "Whether bioavailability is measured as intact ester or hydrolyzed estradiol is unspecified.",
    "In vivo solubility/dissolution behavior of this specific ester is not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

